/* ------------------------------------------------------------------ 9E FB_MotorDol in ST (follows _rules.motor) */
export const ST_MOTOR = `FUNCTION_BLOCK FB_MotorDol
(* Direct-on-line motor: command, run feedback supervision, motor protection.
   Standard program only - the safety stop (STO / contactor pair) is in the F-program. *)
VAR_INPUT
  xCmd      : BOOL;            (* run command from the module sequence *)
  xRunFb    : BOOL;            (* auxiliary contact of the contactor    *)
  xTripped  : BOOL;            (* motor protection breaker tripped (NC) *)
  xReset    : BOOL;            (* alarm reset (rising edge from HMI)    *)
  tFb       : TIME := T#500MS; (* feedback supervision time             *)
END_VAR
VAR_OUTPUT
  qRun      : BOOL;            (* contactor coil                        *)
  iState    : INT;             (* 0 STOPPED 1 STARTING 2 RUNNING 3 STOPPING 9 FAULT *)
  iAlarm    : INT;             (* 1 no fb after start 2 fb lost 3 tripped 4 fb without cmd *)
END_VAR
VAR
  xCmdOld   : BOOL;
  tonFb     : TON;             (* one timer, re-used per state *)
END_VAR

IF xTripped AND iState <> 9 THEN
  iState := 9; iAlarm := 3;                       (* has priority over every state *)
ELSE
  CASE iState OF
  0: (* STOPPED *)
     tonFb(IN := xRunFb, PT := tFb);              (* feedback without command? *)
     IF tonFb.Q THEN iState := 9; iAlarm := 4;
     ELSIF xCmd AND NOT xCmdOld THEN              (* only a RISING edge starts: no automatic restart *)
       iState := 1; tonFb(IN := FALSE);
     END_IF;
  1: (* STARTING *)
     tonFb(IN := TRUE, PT := tFb);
     IF xRunFb THEN iState := 2; tonFb(IN := FALSE);
     ELSIF tonFb.Q THEN iState := 9; iAlarm := 1; END_IF;
  2: (* RUNNING *)
     IF NOT xCmd THEN iState := 3; tonFb(IN := FALSE);
     ELSIF NOT xRunFb THEN iState := 9; iAlarm := 2; END_IF;
  3: (* STOPPING *)
     tonFb(IN := TRUE, PT := tFb);
     IF NOT xRunFb THEN iState := 0; tonFb(IN := FALSE);
     ELSIF tonFb.Q THEN iState := 9; iAlarm := 4; END_IF;
  9: (* FAULT *)
     IF xReset AND NOT xTripped AND NOT (iAlarm = 4 AND xRunFb) THEN
       iState := 0; iAlarm := 0; tonFb(IN := FALSE);   (* back to STOPPED, NOT to RUNNING *)
     END_IF;
  END_CASE;
END_IF;
qRun := (iState = 1) OR (iState = 2);
xCmdOld := xCmd;
END_FUNCTION_BLOCK`;
export const ST_APC = `(* APC01 sequence - runs only in the PackML state Execute (item 5), outputs of the steps *)
CASE iStep OF
10: (* unclamp *)            qClampSol := TRUE;
    IF Clamp.xPosB THEN iStep := 20; tStep(IN := FALSE);
    ELSIF tStep.Q (* 3 s *) THEN iAlarm := 11; xAbortReq := TRUE; END_IF;
20: (* rotate to target *)   qClampSol := TRUE; qSolA := (eTarget = A); qSolB := (eTarget = B);
    IF (eTarget = B AND Rotate.xPosB) OR (eTarget = A AND Rotate.xPosA) THEN iStep := 30;
    ELSIF tStep.Q (* 5 s *) THEN iAlarm := 12; xAbortReq := TRUE; END_IF;
30: (* clamp + pressure *)   qClampSol := FALSE;
    IF Clamp.xPosA AND rClampPress >= 4.5 THEN iStep := 40; xSC := TRUE;   (* State Complete -> Completing *)
    ELSIF tStep.Q (* 3 s *) THEN iAlarm := 13; xAbortReq := TRUE; END_IF;
END_CASE;`;

